from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    grid_area = h * w
    total_tile_area = sum(a * b for a, b in tiles)

    if total_tile_area != grid_area:
        return False

    if n == 0 and grid_area == 0:
        return True

    if n > grid_area:
        return False

    grid = [[0] * w for _ in range(h)]  # 0 represents an empty cell

    def can_place_tile(tile, row, col):
        a, b = tile
        if row + a > h or col + b > w:
            return False
        for i in range(row, row + a):
            for j in range(col, col + b):
                if grid[i][j] != 0:
                    return False
        return True

    def place_tile(tile, row, col, tile_id):
        a, b = tile
        for i in range(row, row + a):
            for j in range(col, col + b):
                grid[i][j] = tile_id

    def remove_tile(tile, row, col):
        a, b = tile
        for i in range(row, row + a):
            for j in range(col, col + b):
                grid[i][j] = 0

    def solve(tile_index):
        if tile_index == n:
            # Check if the entire grid is filled
            for i in range(h):
                for j in range(w):
                    if grid[i][j] == 0:
                        return False
            return True

        for row in range(h):
            for col in range(w):
                if grid[row][col] == 0:
                    for i in range(len(tiles)):
                        tile = tiles[i]

                        # Try original orientation
                        if can_place_tile(tile, row, col):
                            place_tile(tile, row, col, tile_index + 1)
                            if solve(tile_index + 1):
                                return True
                            remove_tile(tile, row, col)  # Backtrack

                        # Try rotated orientation
                        if tile[0] != tile[1]:
                            rotated_tile = (tile[1], tile[0])
                            if can_place_tile(rotated_tile, row, col):
                                place_tile(rotated_tile, row, col, tile_index + 1)
                                if solve(tile_index + 1):
                                    return True
                                remove_tile(rotated_tile, row, col)  # Backtrack
                    return False  # No tile could be placed at this location
        return False  # No empty cell found

    return solve(0)
