                            place_tile(tile, row, col, tile_index + 1)
                            if solve(tile_index + 1):
                                return True
                            remove_tile(tile, row, col)  # Backtrack
                    return solve(tile_index) #attempt to solve with a different starting location

        return False  # No empty cell found

