        """Checks if a tile can be placed at the given position."""
        if row + tile_height > h or col + tile_width > w:
            return False
        for r in range(row, row + tile_height):
            for c in range(col, col + tile_width):
                if grid[r][c] != 0:
                    return False
        return True

    def place_tile(row: int, col: int, tile_height: int, tile_width: int, tile_id: int) -> None:
        """Places the tile on the grid."""
        for r in range(row, row + tile_height):
            for c in range(col, col + tile_width):
                grid[r][c] = tile_id

    def remove_tile(row: int, col: int, tile_height: int, tile_width: int) -> None:
        """Removes the tile from the grid."""
        for r in range(row, row + tile_height):
            for c in range(col, col + tile_width):
                grid[r][c] = 0

    def solve() -> bool:
        """Recursive function to solve the tiling problem."""
        nonlocal tiles_used

        # Find the next empty cell
        for row in range(h):
            for col in range(w):
                if grid[row][col] == 0:
                    # Try placing each tile at this cell
                    for i in range(len(tiles)):
